// Parse and validate input
const input = $input.first().json;
const body = input.body || input;

const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen',
  'de': 'allemand',
  'it': 'italien'
};

if (!body.text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TEXT', message: 'text is required' }
    }
  }];
}

if (!body.api_key) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_API_KEY', message: 'api_key is required' }
    }
  }];
}

const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const needsPivot = sourceLanguage !== 'en' && targetLanguage !== 'en';

return [{
  json: {
    jobId: body.job_id,
    text: body.text,
    sourceLanguage: sourceLanguage,
    sourceLangName: languageNames[sourceLanguage] || sourceLanguage,
    targetLanguage: targetLanguage,
    targetLangName: languageNames[targetLanguage] || targetLanguage,
    needsPivot: needsPivot,
    apiKey: body.api_key,
    model: body.model || 'claude-sonnet-4-20250514',
    context: body.context || {},
    metadata: body.metadata || {}
  }
}];

// Extract English translation from pivot step 1
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  const body = input.body || input;

  if (body.error) {
    return [{
      json: {
        success: false,
        error: { code: 'CLAUDE_ERROR', message: body.error.message || 'Claude API error' }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'Claude returned empty response' }
      }
    }];
  }

  return [{
    json: {
      ...prevData,
      intermediateTranslation: content,
      pivotTokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}

// Extract final translation from pivot step 2
const input = $input.first().json;
const prevData = $('Extract Step 1').first().json;

try {
  const body = input.body || input;

  if (body.error) {
    return [{
      json: {
        success: false,
        error: { code: 'CLAUDE_ERROR', message: body.error.message || 'Claude API error in step 2' }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'Claude returned empty response in step 2' }
      }
    }];
  }

  return [{
    json: {
      success: true,
      translation: content,
      method: 'pivot',
      tokens: {
        input_tokens: (prevData.pivotTokens?.input_tokens || 0) + (usage.input_tokens || 0),
        output_tokens: (prevData.pivotTokens?.output_tokens || 0) + (usage.output_tokens || 0)
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}

